import{_ as a,c as o,o as t,ag as i}from"./chunks/framework.DfL_BkQ-.js";const p=JSON.parse('{"title":"Downloads & Library","description":"","frontmatter":{},"headers":[],"relativePath":"guide/downloads.md","filePath":"guide/downloads.md","lastUpdated":1791309864000}'),l={name:"guide/downloads.md"};function s(r,e,n,d,h,c){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="downloads-library" tabindex="-1">Downloads &amp; Library <a class="header-anchor" href="#downloads-library" aria-label="Permalink to &quot;Downloads &amp; Library&quot;">​</a></h1><p>nPlyr can save streaming playlists to a real file and let you start watching before the download finishes. Your history, bookmarks and downloads are collected in the Library.</p><h2 id="downloading-an-hls-playlist" tabindex="-1">Downloading an HLS playlist <a class="header-anchor" href="#downloading-an-hls-playlist" aria-label="Permalink to &quot;Downloading an HLS playlist&quot;">​</a></h2><p>When you send an <code>m3u8</code> to the downloader, nPlyr:</p><ol><li>Fetches the master and child playlists (validating the HTTP status and that the body is a real <code>#EXTM3U</code> document).</li><li>Downloads every segment, rejecting blank or malformed segment lines so a 404 error page can never be mistaken for a playlist.</li><li>Remuxes the segments into an <strong>MP4</strong> container.</li></ol><h3 id="on-disk-layout" tabindex="-1">On-disk layout <a class="header-anchor" href="#on-disk-layout" aria-label="Permalink to &quot;On-disk layout&quot;">​</a></h3><ul><li>While downloading: <code>&lt;name&gt;.temp/</code></li><li>When finished: renamed to <code>&lt;name&gt;/</code> with the movie at <code>&lt;name&gt;/&lt;name&gt;.mp4</code>.</li><li>If remux fails, the raw <code>.ts</code> is kept and marked <code>completed</code> (not <code>failed</code>) so you don&#39;t lose data; a per-segment failure is marked <code>.failed</code>.</li><li>Resume works from the marker files and manifest — you can pause and continue.</li></ul><blockquote><p>Any custom request <strong>headers</strong> (referer, cookie, auth) captured by the <a href="/guide/browser.html">sniffer</a> are preserved and sent with every request. nPlyr never fakes a referer or origin — it only adds a user-agent when one is needed.</p></blockquote><h2 id="progressive-playback" tabindex="-1">Progressive playback <a class="header-anchor" href="#progressive-playback" aria-label="Permalink to &quot;Progressive playback&quot;">​</a></h2><p>Turn this on to <strong>watch while downloading</strong>. nPlyr serves the partially downloaded file through a local loopback server and begins playback ahead of the download front (<code>progressiveLookahead = 20</code> segments). It is <strong>off by default</strong>.</p><p>When progressive playback is active:</p><ul><li>the playlist&#39;s key (<code>#EXT-X-KEY</code>) lines are stripped before delivery,</li><li>the player always references the <strong>original</strong> source URL (the local server is transparent),</li><li>if a domain fails, that domain is blacklisted for the session, the partial file is cancelled and deleted, and nPlyr does not silently reroute.</li></ul><p>Progressive playback and ad-blocking are mutually exclusive; ad-blocking takes over only when progressive playback is not in use.</p><h2 id="multi-quality-subtitles" tabindex="-1">Multi-quality &amp; subtitles <a class="header-anchor" href="#multi-quality-subtitles" aria-label="Permalink to &quot;Multi-quality &amp; subtitles&quot;">​</a></h2><ul><li><strong>Quality</strong> selection applies to <strong>downloads</strong> (pick a variant before downloading; if you don&#39;t choose, nPlyr waits briefly for a choice and otherwise falls back to the best variant).</li><li><strong>Subtitles</strong> are downloaded alongside the media and saved as <code>subtitle.&lt;ext&gt;</code> in the segment temp directory, so they stay attached to the file.</li></ul><h2 id="media-library" tabindex="-1">Media Library <a class="header-anchor" href="#media-library" aria-label="Permalink to &quot;Media Library&quot;">​</a></h2><p>The Library gathers three things in one searchable place:</p><ul><li><strong>History</strong> — what you&#39;ve watched and when.</li><li><strong>Bookmarks</strong> — sources and items you saved.</li><li><strong>Downloads</strong> — files saved through the downloader.</li></ul><p>Everything is searchable by title, and the library is designed to sync across your Mac and iPhone when signed into the same environment.</p><h2 id="ad-blocking" tabindex="-1">Ad-blocking <a class="header-anchor" href="#ad-blocking" aria-label="Permalink to &quot;Ad-blocking&quot;">​</a></h2><p>nPlyr blocks ads using the same <strong>subscription-rule</strong> format as Chrome extension blocklists (the approach hikerView uses). You subscribe to a filter list and nPlyr filters requests in the browser and during playback. This is separate from progressive playback — only one of the two is active at a time.</p>',21)])])}const g=a(l,[["render",s]]);export{p as __pageData,g as default};
